body { margin: 0; font-family: system-ui, sans-serif; background: #f2f4f7; color: #1d2330; }
header { display: flex; justify-content: space-between; align-items: center; padding: 0.75rem 1.25rem; background: #22324a; color: #fff; }
header h1 { margin: 0; font-size: 1.25rem; }
main { padding: 1.25rem; }
button { cursor: pointer; padding: 0.35rem 0.7rem; border: 1px solid #9aa5b8; border-radius: 4px; background: #fff; }
