#status.error { color: #b00020; }
.card-form { display: flex; flex-direction: column; gap: 0.5rem; max-width: 320px; background: #fff; padding: 1rem; border-radius: 6px; }
.card-form label { display: flex; flex-direction: column; font-size: 0.9rem; }
