.card[draggable="true"] { cursor: grab; }
.card-title { font-weight: 600; }
.card-desc { font-size: 0.85rem; color: #4a5366; margin-top: 0.2rem; }
.card-meta { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.3rem; font-size: 0.8rem; }
.label { color: #fff; padding: 0 0.4rem; border-radius: 3px; }
.due { color: #6b7385; }
.card-actions { display: flex; gap: 0.25rem; margin-top: 0.4rem; }
.add-card { display: flex; gap: 0.3rem; }
.add-card input { flex: 1; min-width: 0; }

